/**
 * Training data generation and management
 * Generates synthetic cross-sensor tactile datasets
 */

import { generateSensorReading, generateContactParams, applyDomainRandomization } from '../algorithms/sensorSimulation';

// Generate a batch of training examples
export function generateTrainingBatch(batchSize, config) {
  const { sensors, materials, tasks, augmentation } = config;

  const batch = {
    anchors: [],
    positives: [],
    negatives: [],
    labels: [],
    metadata: []
  };

  for (let i = 0; i < batchSize; i++) {
    // Random sensor, material, and task
    const sensorA = sensors[Math.floor(Math.random() * sensors.length)];
    const sensorB = sensors[Math.floor(Math.random() * sensors.length)];
    const material = materials[Math.floor(Math.random() * materials.length)];
    const task = tasks[Math.floor(Math.random() * tasks.length)];

    const time = Math.random() * 10;
    const contactParams = generateContactParams(task, time);

    // Generate positive pair (same contact, different sensors)
    let readingA = generateSensorReading(sensorA, contactParams, material);
    let readingB = generateSensorReading(sensorB, contactParams, material);

    if (augmentation) {
      readingA = applyDomainRandomization(readingA, augmentation.strength || 0.3);
      readingB = applyDomainRandomization(readingB, augmentation.strength || 0.3);
    }

    // Generate negative pair (different contact)
    const negTime = Math.random() * 10;
    const negMaterial = materials[Math.floor(Math.random() * materials.length)];
    const negContactParams = generateContactParams(task, negTime);
    let negReading = generateSensorReading(sensorA, negContactParams, negMaterial);

    if (augmentation) {
      negReading = applyDomainRandomization(negReading, augmentation.strength || 0.3);
    }

    batch.anchors.push(readingA);
    batch.positives.push(readingB);
    batch.negatives.push(negReading);
    batch.labels.push({
      sensorA,
      sensorB,
      material,
      task,
      force: contactParams.force,
      position: contactParams.position
    });
    batch.metadata.push({
      time,
      contactParams
    });
  }

  return batch;
}

// Generate evaluation dataset
export function generateEvalDataset(numSamples, sensors, materials, tasks) {
  const dataset = [];

  for (let i = 0; i < numSamples; i++) {
    const sensorType = sensors[i % sensors.length];
    const material = materials[i % materials.length];
    const task = tasks[Math.floor(i / sensors.length) % tasks.length];

    const time = i * 0.5;
    const contactParams = generateContactParams(task, time);
    const reading = generateSensorReading(sensorType, contactParams, material);

    dataset.push({
      reading,
      sensor: sensorType,
      material,
      task,
      contactParams,
      id: i
    });
  }

  return dataset;
}

// Split dataset into train/val/test
export function splitDataset(dataset, ratios = [0.7, 0.15, 0.15]) {
  const n = dataset.length;
  const trainEnd = Math.floor(n * ratios[0]);
  const valEnd = trainEnd + Math.floor(n * ratios[1]);

  return {
    train: dataset.slice(0, trainEnd),
    val: dataset.slice(trainEnd, valEnd),
    test: dataset.slice(valEnd)
  };
}

// Compute dataset statistics
export function computeDatasetStats(dataset) {
  const sensorCounts = {};
  const materialCounts = {};
  const taskCounts = {};

  let totalForce = 0;
  let totalShear = 0;

  dataset.forEach(sample => {
    sensorCounts[sample.sensor] = (sensorCounts[sample.sensor] || 0) + 1;
    materialCounts[sample.material] = (materialCounts[sample.material] || 0) + 1;
    taskCounts[sample.task] = (taskCounts[sample.task] || 0) + 1;

    totalForce += sample.contactParams.force;
    const shear = sample.contactParams.shear;
    totalShear += Math.sqrt(shear[0]**2 + shear[1]**2);
  });

  return {
    size: dataset.length,
    sensors: sensorCounts,
    materials: materialCounts,
    tasks: taskCounts,
    avgForce: totalForce / dataset.length,
    avgShear: totalShear / dataset.length
  };
}

// Generate synthetic ground truth surface for validation
export function generateGroundTruthSurface(material, numPoints = 256) {
  const points = [];

  const materialShapes = {
    rubber: generateRubberSurface,
    metal: generateMetalSurface,
    plastic: generatePlasticSurface,
    foam: generateFoamSurface,
    wood: generateWoodSurface
  };

  const generator = materialShapes[material] || generatePlasticSurface;
  return generator(numPoints);
}

function generateRubberSurface(numPoints) {
  const points = [];
  const gridSize = Math.sqrt(numPoints);

  for (let i = 0; i < numPoints; i++) {
    const x = (i % gridSize) / gridSize * 2 - 1;
    const y = Math.floor(i / gridSize) / gridSize * 2 - 1;

    // Soft deformation
    const z = -0.3 * Math.exp(-(x*x + y*y) / 0.5) +
              Math.sin(x * 5) * Math.cos(y * 5) * 0.05;

    points.push([x, y, z, 0, 0, 0]); // [x, y, z, fx, fy, fz]
  }

  return points;
}

function generateMetalSurface(numPoints) {
  const points = [];
  const gridSize = Math.sqrt(numPoints);

  for (let i = 0; i < numPoints; i++) {
    const x = (i % gridSize) / gridSize * 2 - 1;
    const y = Math.floor(i / gridSize) / gridSize * 2 - 1;

    // Hard flat surface with small ridges
    const z = -0.1 * Math.exp(-(x*x + y*y) / 0.3) +
              Math.sin(x * 20) * 0.01;

    points.push([x, y, z, 0, 0, 0]);
  }

  return points;
}

function generatePlasticSurface(numPoints) {
  const points = [];
  const gridSize = Math.sqrt(numPoints);

  for (let i = 0; i < numPoints; i++) {
    const x = (i % gridSize) / gridSize * 2 - 1;
    const y = Math.floor(i / gridSize) / gridSize * 2 - 1;

    // Medium deformation
    const z = -0.2 * Math.exp(-(x*x + y*y) / 0.4) +
              Math.sin(x * 10) * Math.cos(y * 10) * 0.03;

    points.push([x, y, z, 0, 0, 0]);
  }

  return points;
}

function generateFoamSurface(numPoints) {
  const points = [];
  const gridSize = Math.sqrt(numPoints);

  for (let i = 0; i < numPoints; i++) {
    const x = (i % gridSize) / gridSize * 2 - 1;
    const y = Math.floor(i / gridSize) / gridSize * 2 - 1;

    // Very soft deformation
    const z = -0.5 * Math.exp(-(x*x + y*y) / 0.8) +
              Math.sin(x * 3) * Math.cos(y * 3) * 0.1;

    points.push([x, y, z, 0, 0, 0]);
  }

  return points;
}

function generateWoodSurface(numPoints) {
  const points = [];
  const gridSize = Math.sqrt(numPoints);

  for (let i = 0; i < numPoints; i++) {
    const x = (i % gridSize) / gridSize * 2 - 1;
    const y = Math.floor(i / gridSize) / gridSize * 2 - 1;

    // Medium-hard with grain texture
    const z = -0.15 * Math.exp(-(x*x + y*y) / 0.35) +
              Math.sin(x * 15) * 0.02 +
              Math.sin(y * 2) * 0.03;

    points.push([x, y, z, 0, 0, 0]);
  }

  return points;
}

// Real-time data streaming simulator
export class DataStreamSimulator {
  constructor(config) {
    this.config = config;
    this.time = 0;
    this.buffer = [];
    this.bufferSize = config.bufferSize || 100;
  }

  step(dt = 0.016) {
    this.time += dt;

    const contactParams = generateContactParams(
      this.config.task || 'connector-insertion',
      this.time
    );

    const readings = {};
    this.config.sensors.forEach(sensor => {
      readings[sensor] = generateSensorReading(
        sensor,
        contactParams,
        this.config.material || 'plastic'
      );
    });

    const sample = {
      time: this.time,
      readings,
      contactParams,
      material: this.config.material
    };

    this.buffer.push(sample);
    if (this.buffer.length > this.bufferSize) {
      this.buffer.shift();
    }

    return sample;
  }

  getBuffer() {
    return this.buffer;
  }

  reset() {
    this.time = 0;
    this.buffer = [];
  }
}
