import React, { useRef, useEffect } from 'react';
import './MetricsDashboard.css';

function MetricCard({ title, value, unit, subtitle, color }) {
  const percentage = typeof value === 'number' ? Math.min(100, value * 100) : 0;

  return (
    <div className="metric-card glass-dark">
      <div className="metric-header">
        <h4>{title}</h4>
      </div>
      <div className="metric-value" style={{ color }}>
        {typeof value === 'number' ? value.toFixed(3) : '---'}
        {unit && <span className="metric-unit">{unit}</span>}
      </div>
      {subtitle && <div className="metric-subtitle">{subtitle}</div>}
      <div className="metric-progress">
        <div
          className="metric-progress-bar"
          style={{
            width: `${percentage}%`,
            background: color
          }}
        />
      </div>
    </div>
  );
}

function LineChart({ data, title, color, height = 100 }) {
  const canvasRef = useRef(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas || !data || data.length === 0) return;

    const ctx = canvas.getContext('2d');
    const width = canvas.width;
    const chartHeight = canvas.height;

    // Clear canvas
    ctx.fillStyle = 'rgba(10, 10, 15, 0.8)';
    ctx.fillRect(0, 0, width, chartHeight);

    // Find min/max for scaling
    const minVal = Math.min(...data, 0);
    const maxVal = Math.max(...data, 0.1);
    const range = maxVal - minVal;

    // Draw grid lines
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.05)';
    ctx.lineWidth = 1;
    for (let i = 0; i <= 4; i++) {
      const y = (i / 4) * chartHeight;
      ctx.beginPath();
      ctx.moveTo(0, y);
      ctx.lineTo(width, y);
      ctx.stroke();
    }

    // Draw line
    ctx.beginPath();
    ctx.strokeStyle = color;
    ctx.lineWidth = 2;

    data.forEach((val, i) => {
      const x = (i / Math.max(data.length - 1, 1)) * width;
      const y = chartHeight - ((val - minVal) / range) * chartHeight;

      if (i === 0) {
        ctx.moveTo(x, y);
      } else {
        ctx.lineTo(x, y);
      }
    });

    ctx.stroke();

    // Draw gradient fill
    if (data.length > 1) {
      ctx.lineTo(width, chartHeight);
      ctx.lineTo(0, chartHeight);
      ctx.closePath();

      const gradient = ctx.createLinearGradient(0, 0, 0, chartHeight);
      gradient.addColorStop(0, color + '40');
      gradient.addColorStop(1, color + '00');
      ctx.fillStyle = gradient;
      ctx.fill();
    }

    // Draw points
    data.forEach((val, i) => {
      const x = (i / Math.max(data.length - 1, 1)) * width;
      const y = chartHeight - ((val - minVal) / range) * chartHeight;

      if (i === data.length - 1) {
        ctx.beginPath();
        ctx.arc(x, y, 4, 0, Math.PI * 2);
        ctx.fillStyle = color;
        ctx.fill();
        ctx.strokeStyle = '#ffffff';
        ctx.lineWidth = 2;
        ctx.stroke();
      }
    });

  }, [data, color]);

  return (
    <div className="line-chart">
      <div className="chart-title">{title}</div>
      <canvas
        ref={canvasRef}
        width={400}
        height={height}
        className="chart-canvas"
      />
    </div>
  );
}

function MetricsDashboard({ metrics, history, simulationTime }) {
  return (
    <div className="metrics-dashboard">
      <div className="metrics-grid">
        <MetricCard
          title="Embedding Alignment"
          value={metrics.alignmentScore}
          subtitle="Cross-sensor similarity"
          color="#00d4ff"
        />
        <MetricCard
          title="Reconstruction Error"
          value={metrics.reconstructionError}
          subtitle="Chamfer distance"
          color="#ff6b00"
        />
        <MetricCard
          title="Training Loss"
          value={metrics.trainingLoss}
          subtitle="InfoNCE loss"
          color="#7b2ff7"
        />
        <MetricCard
          title="Insertion Success"
          value={metrics.insertionSuccess}
          unit="%"
          subtitle="Task completion rate"
          color="#20ff40"
        />
      </div>

      <div className="charts-grid">
        <LineChart
          data={history.alignment}
          title="Alignment Score Over Time"
          color="#00d4ff"
          height={120}
        />
        <LineChart
          data={history.loss}
          title="Training Loss Over Time"
          color="#7b2ff7"
          height={120}
        />
        <LineChart
          data={history.reconstruction}
          title="Reconstruction Error Over Time"
          color="#ff6b00"
          height={120}
        />
      </div>

      <div className="simulation-info">
        <div className="info-item">
          <span className="info-label">Simulation Time:</span>
          <span className="info-value mono">{simulationTime.toFixed(2)}s</span>
        </div>
        <div className="info-item">
          <span className="info-label">Update Rate:</span>
          <span className="info-value mono">20 Hz</span>
        </div>
        <div className="info-item">
          <span className="info-label">Samples Processed:</span>
          <span className="info-value mono">{Math.floor(simulationTime * 20)}</span>
        </div>
      </div>
    </div>
  );
}

export default MetricsDashboard;
