import React, { useState, useEffect, useRef, lazy, Suspense } from 'react';
import './App.css';
import Header from './components/Header';
import ControlPanel from './components/ControlPanel';
import MetricsDashboard from './components/MetricsDashboard';
import { TactileEncoder, infoNCELoss, computeAlignmentScore, tsneProjection } from './algorithms/contrastiveLearning';
import { SurfaceDecoder, chamferDistance } from './algorithms/surfaceReconstruction';
import { generateSensorReading, generateContactParams } from './algorithms/sensorSimulation';
import { DataStreamSimulator, generateGroundTruthSurface } from './data/trainingData';

// Lazy load heavy 3D components
const SurfaceViewer = lazy(() => import('./components/SurfaceViewer'));
const EmbeddingVisualization = lazy(() => import('./components/EmbeddingVisualization'));
const SensorComparison = lazy(() => import('./components/SensorComparison'));
const TrainingMonitor = lazy(() => import('./components/TrainingMonitor'));

function App() {
  // Configuration state
  const [config, setConfig] = useState({
    embeddingDim: 128,
    temperature: 0.07,
    augmentationStrength: 0.3,
    material: 'plastic',
    task: 'connector-insertion',
    activeSensors: ['DIGIT', 'GelSight', 'ReSkin'],
    learningRate: 0.001
  });

  // Simulation state
  const [isRunning, setIsRunning] = useState(false);
  const [simulationTime, setSimulationTime] = useState(0);
  const [currentView, setCurrentView] = useState('main'); // main, comparison, training

  // Model state
  const encodersRef = useRef({});
  const decoderRef = useRef(null);
  const [embeddings, setEmbeddings] = useState({});
  const [surfacePoints, setSurfacePoints] = useState([]);
  const [groundTruthPoints, setGroundTruthPoints] = useState([]);

  // Metrics state
  const [metrics, setMetrics] = useState({
    alignmentScore: 0,
    reconstructionError: 0,
    trainingLoss: 0,
    insertionSuccess: 0
  });

  const [trainingHistory, setTrainingHistory] = useState({
    loss: [],
    alignment: [],
    reconstruction: []
  });

  // Data stream
  const streamSimulatorRef = useRef(null);

  // Initialize models
  useEffect(() => {
    // Initialize encoders for each sensor
    const sensorDims = {
      'DIGIT': 1024,      // 32x32 image
      'GelSight': 512,    // 16x16 markers * 2
      'ReSkin': 15        // 5 magnetometers * 3
    };

    config.activeSensors.forEach(sensor => {
      if (!encodersRef.current[sensor]) {
        encodersRef.current[sensor] = new TactileEncoder(
          sensorDims[sensor],
          config.embeddingDim
        );
      }
    });

    // Initialize decoder
    if (!decoderRef.current) {
      decoderRef.current = new SurfaceDecoder(config.embeddingDim, 256);
    }

    // Initialize data stream
    streamSimulatorRef.current = new DataStreamSimulator({
      sensors: config.activeSensors,
      material: config.material,
      task: config.task,
      bufferSize: 100
    });

    // Generate ground truth
    setGroundTruthPoints(generateGroundTruthSurface(config.material, 256));
  }, [config.activeSensors, config.embeddingDim, config.material, config.task]);

  // Simulation loop
  useEffect(() => {
    if (!isRunning) return;

    const interval = setInterval(() => {
      setSimulationTime(t => t + 0.05);

      // Generate sensor readings
      const sample = streamSimulatorRef.current.step(0.05);

      // Encode readings from each sensor
      const newEmbeddings = {};
      const embeddingsList = [];

      config.activeSensors.forEach(sensor => {
        const reading = sample.readings[sensor];
        const encoder = encodersRef.current[sensor];
        const embedding = encoder.forward(reading);
        newEmbeddings[sensor] = embedding;
        embeddingsList.push(embedding);
      });

      setEmbeddings(newEmbeddings);

      // Decode to surface reconstruction (use first sensor's embedding)
      if (embeddingsList.length > 0) {
        const points = decoderRef.current.decode(embeddingsList[0]);
        setSurfacePoints(points);

        // Compute metrics
        updateMetrics(newEmbeddings, points);
      }

      // Training step (simulate weight updates)
      if (Math.random() < 0.1) { // Train every ~10 steps
        performTrainingStep(newEmbeddings);
      }

    }, 50); // 20 Hz

    return () => clearInterval(interval);
  }, [isRunning, config]);

  const updateMetrics = (embs, points) => {
    // Alignment score between sensors
    const sensors = Object.keys(embs);
    if (sensors.length >= 2) {
      const alignment = computeAlignmentScore(
        [embs[sensors[0]]],
        [embs[sensors[1]]]
      );

      // Reconstruction error
      const gtPoints = groundTruthPoints.map(p => [p[0], p[1], p[2]]);
      const predPoints = points.map(p => [p[0], p[1], p[2]]);
      const reconError = chamferDistance(predPoints, gtPoints);

      // Insertion success (based on reconstruction quality)
      const successRate = Math.max(0, Math.min(1, 1 - reconError * 2));

      // Training loss (InfoNCE between first two sensors)
      let loss = 0;
      if (sensors.length >= 2) {
        const negatives = sensors.slice(2).map(s => embs[s]);
        if (negatives.length === 0) {
          // Generate synthetic negative
          negatives.push(embs[sensors[0]].map(() => Math.random() - 0.5));
        }
        loss = infoNCELoss(
          embs[sensors[0]],
          embs[sensors[1]],
          negatives,
          config.temperature
        );
      }

      setMetrics({
        alignmentScore: alignment,
        reconstructionError: reconError,
        trainingLoss: loss,
        insertionSuccess: successRate
      });

      // Update history
      setTrainingHistory(prev => ({
        loss: [...prev.loss.slice(-99), loss],
        alignment: [...prev.alignment.slice(-99), alignment],
        reconstruction: [...prev.reconstruction.slice(-99), reconError]
      }));
    }
  };

  const performTrainingStep = (embs) => {
    // Simulate training by updating encoder weights
    Object.values(encodersRef.current).forEach(encoder => {
      encoder.updateWeights(config.learningRate);
    });
  };

  const handleConfigChange = (key, value) => {
    setConfig(prev => ({
      ...prev,
      [key]: value
    }));

    // Reset simulation time when changing major parameters
    if (['material', 'task', 'activeSensors'].includes(key)) {
      setSimulationTime(0);
      if (streamSimulatorRef.current) {
        streamSimulatorRef.current.reset();
      }
    }
  };

  const handleSensorHotSwap = (sensor, enabled) => {
    const newSensors = enabled
      ? [...config.activeSensors, sensor]
      : config.activeSensors.filter(s => s !== sensor);

    handleConfigChange('activeSensors', newSensors);
  };

  const toggleSimulation = () => {
    setIsRunning(!isRunning);
  };

  const resetSimulation = () => {
    setIsRunning(false);
    setSimulationTime(0);
    setMetrics({
      alignmentScore: 0,
      reconstructionError: 0,
      trainingLoss: 0,
      insertionSuccess: 0
    });
    setTrainingHistory({
      loss: [],
      alignment: [],
      reconstruction: []
    });
    if (streamSimulatorRef.current) {
      streamSimulatorRef.current.reset();
    }
  };

  return (
    <div className="app">
      <Header />

      <div className="app-container">
        {/* View Tabs */}
        <div className="view-tabs">
          <button
            className={currentView === 'main' ? 'active' : ''}
            onClick={() => setCurrentView('main')}
          >
            Surface Reconstruction
          </button>
          <button
            className={currentView === 'comparison' ? 'active' : ''}
            onClick={() => setCurrentView('comparison')}
          >
            Sensor Comparison
          </button>
          <button
            className={currentView === 'training' ? 'active' : ''}
            onClick={() => setCurrentView('training')}
          >
            Training Monitor
          </button>
        </div>

        {/* Control Panel */}
        <ControlPanel
          config={config}
          isRunning={isRunning}
          onConfigChange={handleConfigChange}
          onToggleSimulation={toggleSimulation}
          onReset={resetSimulation}
          onSensorHotSwap={handleSensorHotSwap}
        />

        {/* Main Content */}
        <div className="main-content">
          <Suspense fallback={<div className="loading-spinner">Loading visualization...</div>}>
            {currentView === 'main' && (
              <>
                <div className="visualization-grid">
                  <div className="viz-panel">
                    <h3>3D Surface Reconstruction</h3>
                    <SurfaceViewer
                      points={surfacePoints}
                      groundTruth={groundTruthPoints}
                      material={config.material}
                    />
                  </div>

                  <div className="viz-panel">
                    <h3>Embedding Space (t-SNE)</h3>
                    <EmbeddingVisualization
                      embeddings={embeddings}
                      activeSensors={config.activeSensors}
                    />
                  </div>
                </div>

                <MetricsDashboard
                  metrics={metrics}
                  history={trainingHistory}
                  simulationTime={simulationTime}
                />
              </>
            )}

            {currentView === 'comparison' && (
              <SensorComparison
                embeddings={embeddings}
                activeSensors={config.activeSensors}
                alignmentScore={metrics.alignmentScore}
              />
            )}

            {currentView === 'training' && (
              <TrainingMonitor
                history={trainingHistory}
                config={config}
                metrics={metrics}
              />
            )}
          </Suspense>
        </div>
      </div>
    </div>
  );
}

export default App;
